// Runs on a schedule (every 3 minutes). Checks system_errors for anything
// not yet reported, sends each seller a Telegram message summarizing what
// went wrong, then marks those rows as notified so they're not repeated.

const anonKey = '[REDACTED_SUPABASE_ANON_KEY]';
const botToken = '[REDACTED_TELEGRAM_BOT_TOKEN]';

let unnotified = [];
try {
  unnotified = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/system_errors?notified=eq.false&select=id,seller_id,source,error_message,created_at&order=created_at.asc&limit=200',
    headers: { apikey: anonKey, Authorization: 'Bearer ' + anonKey }
  });
} catch (e) {
  return [{ json: { success: false, reason: 'Could not fetch system_errors: ' + e.message } }];
}

if (!unnotified || unnotified.length === 0) {
  return [{ json: { success: true, notified: 0 } }];
}

const bySeller = {};
for (const row of unnotified) {
  const key = row.seller_id || 'unknown';
  if (!bySeller[key]) bySeller[key] = [];
  bySeller[key].push(row);
}

const notifiedIds = [];

for (const sellerId of Object.keys(bySeller)) {
  if (sellerId === 'unknown') { unnotified.forEach(r => notifiedIds.push(r.id)); continue; }
  const errors = bySeller[sellerId];
  const lines = errors.slice(0, 10).map(e =>
    '• ' + e.source + ': ' + e.error_message.slice(0, 150)
  ).join('\n');
  const extra = errors.length > 10 ? '\n...and ' + (errors.length - 10) + ' more' : '';
  const text = '⚠️ ' + errors.length + ' issue' + (errors.length > 1 ? 's' : '') + ' detected in your app:\n\n' + lines + extra +
    '\n\nCheck Settings → Error Log in the app for full details.';

  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + botToken + '/sendMessage',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ chat_id: sellerId, text })
    });
  } catch (e) {}

  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/seller_web_chat_log',
      headers: { apikey: anonKey, Authorization: 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
      body: JSON.stringify({ seller_id: sellerId, role: 'ahmad', message: text })
    });
  } catch (e) {}

  errors.forEach(e => notifiedIds.push(e.id));
}

try {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: 'https://qfmmoobwzuhiimmjixes.supabase.co/rest/v1/system_errors?id=in.(' + notifiedIds.join(',') + ')',
    headers: { apikey: anonKey, Authorization: 'Bearer ' + anonKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
    body: JSON.stringify({ notified: true })
  });
} catch (e) {}

return [{ json: { success: true, notified: notifiedIds.length } }];
